        } else if (Objects.equals(animation, "attack")){
            return 2;
        } else if (Objects.equals(animation, "walk")){
            return 3;
        } else if (Objects.equals(animation, "roar")){
            return 4;
        } else if (Objects.equals(animation, "to_sit")){
