    public void handleEntityEvent(byte pId) {
        if (pId == 5){
            this.attackTick = 0;
        } else if (pId == 6){
            this.stopAnimations();
            this.attackAnimationState.start(this.tickCount);
        } else if (pId == 8){
            this.stopAnimations();
            this.activateAnimationState.start(this.tickCount);
        } else if (pId == 11){
            this.attackAnimationState.stop();
        } else if (pId == 12){
            this.stopAnimations();
            this.deactivateAnimationState.start(this.tickCount);
        } else if (pId == 13){
            this.stopAnimations();
            this.offAnimationState.start(this.tickCount);
        } else if (pId == 17){
            this.setMeleeAttacking(true);
        } else if (pId == 18){
            this.setMeleeAttacking(false);
        } else if (pId == 19){
            this.setAggressive(true);
        } else if (pId == 31){
            this.setAggressive(false);
        } else if (pId == 22){
            this.isNovelty = true;
        } else if (pId == 23){
            this.isNovelty = false;
            this.noveltyTick = 0;
        } else if (pId == 24){
            ++this.noveltyTick;
        } else if (pId == 25){
            this.setStartingUp(true);
        } else if (pId == 26){
            this.setShuttingDown(true);
        } else if (pId == 27){
            this.setStartingUp(false);
        } else if (pId == 28){
            this.setShuttingDown(false);
        } else if (pId == 29){
            this.setActivated(true);
        } else if (pId == 30){
            this.setActivated(false);
        } else {
            super.handleEntityEvent(pId);
        }
    }

